properties.query:
let baselineWindow = 24h;
let alertWindow = 15m;
let binSize = 5m;
let gateMultiplier = 2.0;
let floorBytes = 500000000.0;
let dynGate = toscalar(
    UAVSarPayload_CL
    | where TimeGenerated > ago(baselineWindow)
    | summarize SumBytes = sum(SizeBytes) by UAVId, bin(TimeGenerated, binSize)
    | summarize gate = percentile(SumBytes, 99) * gateMultiplier
);
let volGate = max_of(dynGate, floorBytes);
UAVSarPayload_CL
| where TimeGenerated > ago(alertWindow)
| summarize SumBytes = sum(SizeBytes), FrameCount = count()
    by UAVId, TimeBin = bin(TimeGenerated, binSize)
| where SumBytes > volGate
| extend TriggerReason = strcat("대량SAR영상유출_버스트_", tostring(toint(SumBytes/1000000)), "MB/5min_게이트_", tostring(toint(volGate/1000000)), "MB")
| extend Severity = "High"
| project TimeGenerated = TimeBin, UAVId, SumBytes, FrameCount, TriggerReason, Severity
| order by TimeGenerated desc
